INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على أبرز النصائح العملية والعلمية للمزارعين العراقيين حول تقنيات الحفظ والاستخدام الأمثل لشريط T Tip لحماية محصول البطيخ، بناءً على معايير الزراعة الحديثة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
