INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','استعراض شامل لكل التكاليف المرتبطة بزراعة القمح باستخدام شريط تيبرو في العراق. دليل دقيقتي لتقليل النفقات وتحقيق أفضل عائد مع مراعاة الظروف المحلية، من إعداد AFP.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
